// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle } from '@stdlib/types/blas';

/**
* Interface describing `dpstf2`.
*/
interface Routine {
	/**
	* Computes an unblocked Cholesky factorization with complete pivoting in place.
	*
	* ## Notes
	*
	* -   INFO is numeric, independent of the one-element RANK output.
	* -   PIV is the complete positive 1-based permutation, including early termination; incoming PIV/RANK values are not input.
	* -   INFO=1 reports an early cutoff or deficient/nonpositive remainder, not positive semidefiniteness certification.
	* -   The first positive maximum diagonal is accepted before testing TOL; later candidates stop at or below the cutoff.
	* -   Negative TOL requests N*2^-53*max(initial diagonal); TOL must always be a primitive finite number.
	* -   Only the selected triangle changes; WORK is mutable 2N output scratch, not a factorization result.
	* -   Full active indexed views must fit, the matrix must be injective, and all four indexed-byte envelopes must be disjoint.
	* -   Active buffers require intrinsic ordinary ArrayBuffer backing; SharedArrayBuffer views are rejected before routine-owned writes.
	* -   Externally aliased ordinary buffers from foreign addons are outside the caller contract; types cannot encode this runtime precondition.
	* -   For N=0, validate scalar selectors/N, finite TOL, main LDA and active RANK, then write only rank zero without inactive buffer/metadata access.
	* -   Inactive storage aliased to RANK may observe the scalar write; this empty behavior is package-defined, not original-reference parity.
	* -   Finite stored-triangle inputs with finite intermediates define the reference-comparison domain; no universal active nonfinite guarantee is given.
	*
	* @param order - row-major (101) or column-major (102) layout
	* @param uplo - upper (121) or lower (122) stored triangle
	* @param N - nonnegative safe integer matrix order, at most 2147483647
	* @param A - input/output N-by-N matrix
	* @param LDA - matrix leading dimension, at least max(1,N)
	* @param PIV - complete positive 1-based permutation output
	* @param RANK - one active Int32 rank output scalar
	* @param TOL - required primitive finite tolerance; negative requests the default cutoff
	* @param WORK - mutable 2N scratch output
	* @throws selectors, primitive TOL, active types and backing stores must be valid
	* @throws dimensions, finite TOL, active metadata, bounds, collisions and aliases must satisfy the preconditions
	* @returns numeric INFO, zero or one
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 4.0, 0.0, 999.0, 1.0 ] );
	* var PIV = new Int32Array( 2 );
	* var RANK = new Int32Array( 1 );
	* var WORK = new Float64Array( 4 );
	*
	* var info = dpstf2( 'row-major', 'upper', 2, A, 2, PIV, RANK, -1.0, WORK );
	* // returns 0
	* // RANK => <Int32Array>[ 2 ]
	* // PIV => <Int32Array>[ 1, 2 ]
	* // A => <Float64Array>[ 2.0, 0.0, 999.0, 1.0 ]
	*/
	( order: Layout | 101 | 102, uplo: MatrixTriangle | 121 | 122, N: number, A: Float64Array, LDA: number, PIV: Int32Array, RANK: Int32Array, TOL: number, WORK: Float64Array ): number;

	/**
	* Computes a pivoted Cholesky factorization with alternative indexing semantics.
	*
	* ## Notes
	*
	* -   INFO is numeric, independent of the one-element RANK output.
	* -   PIV is the complete positive 1-based permutation, including early termination; incoming PIV/RANK values are not input.
	* -   INFO=1 reports an early cutoff or deficient/nonpositive remainder, not positive semidefiniteness certification.
	* -   The first positive maximum diagonal is accepted before testing TOL; later candidates stop at or below the cutoff.
	* -   Negative TOL requests N*2^-53*max(initial diagonal); TOL must always be a primitive finite number.
	* -   Only the selected triangle changes; WORK is mutable 2N output scratch, not a factorization result.
	* -   Full active indexed views must fit, the matrix must be injective, and all four indexed-byte envelopes must be disjoint.
	* -   Active buffers require intrinsic ordinary ArrayBuffer backing; SharedArrayBuffer views are rejected before routine-owned writes.
	* -   Externally aliased ordinary buffers from foreign addons are outside the caller contract; types cannot encode this runtime precondition.
	* -   For N=0, validate scalar selectors/N, finite TOL, main LDA and active RANK, then write only rank zero without inactive buffer/metadata access.
	* -   Inactive storage aliased to RANK may observe the scalar write; this empty behavior is package-defined, not original-reference parity.
	* -   Finite stored-triangle inputs with finite intermediates define the reference-comparison domain; no universal active nonfinite guarantee is given.
	*
	* -   Strides and offsets are element indices relative to actual typed-array views.
	* -   Positive and negative strides are supported; mutable zero strides are rejected when an extent exceeds one.
	*
	* @param uplo - upper (121) or lower (122) stored triangle
	* @param N - nonnegative safe integer matrix order, at most 2147483647
	* @param A - input/output N-by-N matrix
	* @param strideA1 - matrix row stride
	* @param strideA2 - matrix column stride
	* @param offsetA - starting matrix index
	* @param PIV - complete positive 1-based permutation output
	* @param stridePIV - permutation stride
	* @param offsetPIV - starting permutation index
	* @param RANK - one active Int32 rank output scalar
	* @param offsetRANK - index of the active rank scalar
	* @param TOL - required primitive finite tolerance; negative requests the default cutoff
	* @param WORK - mutable 2N scratch output
	* @param strideWORK - scratch stride
	* @param offsetWORK - starting scratch index
	* @throws selectors, primitive TOL, active types and backing stores must be valid
	* @throws dimensions, finite TOL, active metadata, bounds, collisions and aliases must satisfy the preconditions
	* @returns numeric INFO, zero or one
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 9.0, 1.0, 0.0, 999.0, 4.0, 9.0 ] );
	* var PIV = new Int32Array( [ 8, -99, -99, 8 ] );
	* var RANK = new Int32Array( [ 7, -9, 7 ] );
	* var WORK = new Float64Array( 6 );
	*
	* var info = dpstf2.ndarray( 'lower', 2, A, -2, -1, 4, PIV, -1, 2, RANK, 1, -1.0, WORK, -1, 4 );
	* // returns 0
	* // RANK => <Int32Array>[ 7, 2, 7 ]
	* // PIV => <Int32Array>[ 8, 2, 1, 8 ]
	* // A => <Float64Array>[ 9.0, 1.0, 0.0, 999.0, 2.0, 9.0 ]
	*/
	ndarray( uplo: MatrixTriangle | 121 | 122, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, PIV: Int32Array, stridePIV: number, offsetPIV: number, RANK: Int32Array, offsetRANK: number, TOL: number, WORK: Float64Array, strideWORK: number, offsetWORK: number ): number;
}

/**
* Computes an unblocked Cholesky factorization with complete pivoting.
*
* @param order - row-major (101) or column-major (102) layout
* @param uplo - upper (121) or lower (122) stored triangle
* @param N - nonnegative safe integer matrix order, at most 2147483647
* @param A - input/output N-by-N matrix
* @param LDA - matrix leading dimension, at least max(1,N)
* @param PIV - complete positive 1-based permutation output
* @param RANK - one active Int32 rank output scalar
* @param TOL - required primitive finite tolerance; negative requests the default cutoff
* @param WORK - mutable 2N scratch output
* @returns numeric INFO, independent of the mutable rank scalar
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 4.0 ] );
* var PIV = new Int32Array( 1 );
* var RANK = new Int32Array( 1 );
* var WORK = new Float64Array( 2 );
*
* var info = dpstf2( 'column-major', 'lower', 1, A, 1, PIV, RANK, 100.0, WORK );
* // returns 0
* // RANK => <Int32Array>[ 1 ]
*/
declare var dpstf2: Routine;


// EXPORTS //

export = dpstf2;
